@section('page-script')<script src="{{ asset('js/scripts/pages/procurement.js') }}?v=2"></script><script>
(function(){
 const form=document.getElementById('multi-labels'),button=document.getElementById('print-selected-labels'),all=document.getElementById('select-label-orders');
 const choices=Array.from(document.querySelectorAll('input[name="orders[]"][form="multi-labels"]'));
 function update(){const count=choices.filter(input=>input.checked).length;button.disabled=!count || count>20;button.title=count>20?'Najviše 20 nabavki odjednom':(count?'Štampaj etikete označenih nabavki':'Označite nabavke u tabeli');button.querySelector('[data-label-selection-count]').textContent='('+count+')';all.checked=!!choices.length && count===Math.min(choices.length,20);all.indeterminate=count>0 && !all.checked;}
 choices.forEach(input=>input.addEventListener('change',update));all.addEventListener('change',()=>{choices.forEach((input,index)=>input.checked=all.checked && index<20);update();});
 form.addEventListener('submit',event=>{if(!choices.some(input=>input.checked)){event.preventDefault();return;}form.querySelectorAll('input[data-label-order]').forEach(input=>input.remove());choices.filter(input=>input.checked).forEach(choice=>{const input=document.createElement('input');input.type='hidden';input.name='orders[]';input.value=choice.value;input.dataset.labelOrder='1';form.append(input);});choices.forEach(input=>input.removeAttribute('form'));});update();
})();
</script>@endsection
